using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Moonblade (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class Moonblade2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("moonblade", null, 0, MagicItemType.Weapon, ItemRarity.Legendary, true, ContentSource.RealmForge,
			Magic(Effect(MagicEffectKind.AttackAndDamage, 1)),
			("Lama lunare", "Arma (spada lunga), leggendaria (richiede sintonia con un elfo o un mezzelfo di allineamento neutrale buono)",
			"Tra gli oggetti magici creati dagli elfi, le lame lunari sono tra i più preziosi e gelosamente custoditi. Un tempo quasi ogni casata nobile elfica ne possedeva una, ma nei secoli molte sono scomparse con le stirpi estinte o con i loro portatori; oggi ne restano poche.\n\nUna lama lunare passa di genitore in figlio. È la spada a scegliere il suo portatore, a cui resta legata per tutta la vita; alla sua morte un altro erede può reclamarla, e se non esiste un erede degno resta dormiente e funziona come una normale spada lunga. Serve un solo padrone alla volta, e la sintonia richiede un rituale speciale nella sala del trono di un sovrano elfico o in un tempio degli dèi elfici. Non serve chi giudica codardo, incostante, corrotto o contrario alla protezione del popolo elfico: se rifiuta il personaggio, questi subisce svantaggio alle prove di caratteristica, ai tiri per colpire e ai tiri salvezza per 24 ore. Se lo accetta, il personaggio entra in sintonia con essa e sulla lama compare una nuova runa; la sintonia dura finché il personaggio non muore o la spada non viene distrutta.\n\nLa lama ha una runa per ogni padrone che ha servito (di solito 1d6 + 1). La prima runa concede sempre un bonus di +1 ai tiri per colpire e ai danni; ogni runa successiva aggiunge una proprietà scelta dal GM o tirata sulla tabella.\n\n| d100 | Proprietà |\n|---|---|\n| 01–40 | Il bonus ai tiri per colpire e ai danni aumenta di 1, fino a un massimo di +3 (si ritira se è già +3). |\n| 41–80 | La lama ottiene una proprietà minore casuale. |\n| 81–82 | La lama ottiene la proprietà accurata. |\n| 83–84 | La lama ottiene la proprietà da lancio (gittata 6/18 metri). |\n| 85–86 | La lama funziona come una *difensiva*. |\n| 87–90 | La lama mette a segno un colpo critico con un 19 o un 20. |\n| 91–92 | Quando colpisce, l'attacco infligge 1d6 danni taglienti extra. |\n| 93–94 | Quando colpisce una creatura di un tipo specifico (per esempio drago, immondo o non morto), il bersaglio subisce 1d6 danni extra di uno di questi tipi: acido, freddo, fuoco, fulmine o tuono. |\n| 95–96 | Con un'azione bonus la lama emette un lampo accecante: ogni creatura entro 9 metri che può vedere il personaggio deve superare un tiro salvezza su Costituzione con CD 15 o restare accecata per 1 minuto, ripetendo il tiro salvezza alla fine di ogni suo turno. Non si può riusare finché il personaggio non completa un riposo breve mentre è in sintonia con la lama. |\n| 97–98 | La lama funziona come un *anello accumula incantesimi*. |\n| 99 | Con un'azione il personaggio evoca un'ombra elfica, se non ne ha già una al suo servizio: compare entro 36 metri e usa le statistiche di un'ombra, ma è neutrale, immune agli effetti che scacciano i non morti e non crea altre ombre. Il personaggio la controlla; resta finché non scende a 0 punti ferita o finché il personaggio non la congeda con un'azione. |\n| 00 | La lama funziona come una *spada vorpal*. |\n\n***Senzienza.*** Una lama lunare è un'arma senziente neutrale buona con Intelligenza 12, Saggezza 10 e Carisma 12, con udito e scurovisione fino a 36 metri. Comunica trasmettendo emozioni, con un formicolio nella mano di chi la impugna quando ha percepito qualcosa; in modo più esplicito può farlo tramite visioni o sogni, quando il portatore è in trance o addormentato.\n\n***Personalità.*** Ogni lama lunare persegue il progresso del popolo elfico e dei suoi ideali: coraggio, lealtà, bellezza, musica e vita. È legata alla stirpe che deve servire e, una volta scelto un padrone che condivide i suoi ideali, la sua lealtà è assoluta. Il suo difetto è l'eccessiva sicurezza: decisa la persona a cui appartenere, crede che solo lei debba impugnarla, anche quando non è all'altezza degli ideali elfici.", null),
			("Moonblade", "Weapon (longsword), legendary (requires attunement by an elf or half-elf of neutral good alignment)",
			"Among the magic items crafted by the elves, moonblades are some of the most prized and jealously guarded. Once nearly every elven noble house had one, but over the centuries many vanished with extinct bloodlines or with their bearers; few remain today.\n\nA moonblade passes from parent to child. The sword chooses its bearer and stays bonded to them for life; when the bearer dies, another heir can claim it, and if there is no worthy heir it lies dormant and works as an ordinary longsword. It serves one master at a time, and attuning to it requires a special ritual in the throne room of an elven ruler or in a temple of the elven gods. It won't serve anyone it judges cowardly, erratic, corrupt or opposed to protecting elvenkind: if it rejects you, you have disadvantage on ability checks, attack rolls and saving throws for 24 hours. If it accepts you, you become attuned to it and a new rune appears on the blade; you stay attuned until you die or the sword is destroyed.\n\nThe blade has one rune for each master it has served (usually 1d6 + 1). The first rune always grants a +1 bonus to attack and damage rolls; each further rune adds a property chosen by the DM or rolled on the table.\n\n| d100 | Property |\n|---|---|\n| 01–40 | The bonus to attack and damage rolls increases by 1, to a maximum of +3 (reroll if it is already +3). |\n| 41–80 | The blade gains a random minor property. |\n| 81–82 | The blade gains the finesse property. |\n| 83–84 | The blade gains the thrown property (range 20/60 feet). |\n| 85–86 | The blade works as a *defender*. |\n| 87–90 | The blade scores a critical hit on a roll of 19 or 20. |\n| 91–92 | When you hit with it, the attack deals an extra 1d6 slashing damage. |\n| 93–94 | When you hit a creature of a specific type (such as dragon, fiend or undead), the target takes an extra 1d6 damage of one of these types: acid, cold, fire, lightning or thunder. |\n| 95–96 | As a bonus action, the blade flashes brightly: each creature within 30 feet that can see you must succeed on a DC 15 Constitution saving throw or be blinded for 1 minute, repeating the save at the end of each of its turns. It can't be used again until you finish a short rest while attuned to the blade. |\n| 97–98 | The blade works as a *ring of spell storing*. |\n| 99 | As an action, you call forth an elfshadow if you don't already have one serving you: it appears within 120 feet and uses the statistics of a shadow, except it is neutral, immune to effects that turn undead, and doesn't create new shadows. You control it; it remains until it drops to 0 hit points or you dismiss it as an action. |\n| 00 | The blade works as a *vorpal sword*. |\n\n***Sentience.*** A moonblade is a sentient neutral good weapon with Intelligence 12, Wisdom 10 and Charisma 12, with hearing and darkvision out to 120 feet. It communicates by sending emotions, a tingling in its wielder's hand when it has sensed something; more explicitly it can use visions or dreams while its bearer is in a trance or asleep.\n\n***Personality.*** Every moonblade seeks to advance elvenkind and its ideals: courage, loyalty, beauty, music and life. It is bonded to the bloodline it is meant to serve and, once it has chosen a master who shares its ideals, its loyalty is absolute. Its flaw is overconfidence: once it has picked its owner, it believes only that person should wield it, even when they fall short of elven ideals.", null));
	}
}
